import{_ as n,a0 as o,w as r,s,ao as d,I as a,a1 as e,A as p,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Picty:让图片管理变简单 | LCTT x X-CMD","titleTemplate":false,"description":"Picty:让图片管理变简单 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Picty:让图片管理变简单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Picty:让图片管理变简单 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150330 Picty--Managing Photos Made Easy","title":"Picty:让图片管理变简单","tag":"201504","desc":""},"relativePath":"201504/20150330 Picty--Managing Photos Made Easy.md","filePath":"[post].md"}'),u={name:"201504/20150330 Picty--Managing Photos Made Easy.md"};function y(c,t,m,g,P,h){const l=o("Link");return r(),s("div",null,[t[14]||(t[14]=d(`<h1 id="picty-让图片管理变简单" tabindex="-1">Picty:让图片管理变简单 <a class="header-anchor" href="#picty-让图片管理变简单" aria-label="Permalink to “Picty:让图片管理变简单”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/03/picty_002-790x429.png" alt=""></p><h3 id="关于picty" tabindex="-1">关于Picty <a class="header-anchor" href="#关于picty" aria-label="Permalink to “关于Picty”">​</a></h3><p><strong>Picty</strong>是个免费，简单，却强大的照片收藏管理器，它可以帮助你管理你的照片。它是围绕着<strong>元数据</strong>管理和图像<strong>无损</strong>处理设计的。Picty目前同时支持在线（基于网页的）和离线（本地的）收藏集。在本地的收藏集中，图片将被保存在一个本地的文件夹及其子文件夹中。为了加快用户主目录里图片的查询速度，它会维持一个数据库。在在线（基于网页的）收藏集中，你可以通过网页浏览器上传并分享图片。拥有适当权限的个人用户可以把图片分享给任何人，而且用户可以同时打开多个收藏集，收藏集也可以分享给多个用户。有个简单的界面可以通过传输插件在收藏集之间传输图片。</p><p>你可以从你的相机或任何设备中下载任何数量的照片。除此之外，Picty允许你在下载前浏览在你相机里的图片集。Picty是个轻量级的应用，界面清爽。它支持Linux和Windows平台。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><ul><li>支持大相片集（20000张以上）。</li><li>同时打开多个收藏集，还可以在它们之间传照片。</li><li>收藏集包括： <ul><li>本地文件系统中保存图片的文件夹。</li><li>相机、电话及其他媒体设备中的图片。</li><li>图片保存服务（目前支持Flickr）</li></ul></li><li>Picty不是把相片“导入”到它的数据库中，它仅仅提供了一个界面来访问它们，不管它们保存在哪。为了保持迅速的反应以及能使你在离线时浏览图片的能力，Picty会保存缩略图和元数据的缓存。</li><li>以业界标准格式Exif、IPTC和Xmp读写元数据。</li><li>无损的方法： <ul><li>Picty把所有改变包括图像编辑以元数据的方式写入。例如，一个图片可以以任何方式剪切保存，原来的图像仍然保存在该文件里。</li><li>修改会保存在Picty的收藏集缓存中直到你把你对元数据的修改保存到图片中，所以你能很容易撤销你不喜欢的未保存的修改。</li></ul></li><li>基本图片编辑功能： <ul><li>目前支持基本的图像增强，如亮度、对比度、色彩、剪切以及矫正。</li><li>将要推出一些工具改进及更多工具。（红眼消除、拉伸、弯曲、噪声消除）</li></ul></li><li>图片标签： <ul><li>使用标准的IPTC和Xmp关键词为图片做标签。</li><li>一个树状标签图让你能很容易的管理标签和在收藏集内导航。</li></ul></li><li>文件夹视图： <ul><li>按照目录的结构对你的图片收藏集进行导航</li></ul></li><li>支持多屏显示 <ul><li>Picty可以设置成让你在一个屏幕上浏览你的收藏集同时在另一个屏幕上全屏显示图片。</li></ul></li><li>可个性化 <ul><li>可以为外部工具创建快捷方式</li><li>支持插件——目前提供的功能中有许多（标签和文件夹视图以及所有的图片编辑工具）都可以通过插件提供。</li><li>使用Python编写——内置电池(batteries included)！</li></ul></li></ul><h3 id="安装方法" tabindex="-1">安装方法 <a class="header-anchor" href="#安装方法" aria-label="Permalink to “安装方法”">​</a></h3><h4 id="_1、从ppa安装" tabindex="-1">1、从PPA安装 <a class="header-anchor" href="#_1、从ppa安装" aria-label="Permalink to “1、从PPA安装”">​</a></h4><p>Picty开发人员为Ubuntu这样的基于 Debian的发行版创建了一个PPA，让安装更简单。</p><p>要在Ubuntu和它的衍生版上安装，请运行以下命令：</p><pre><code>sudo add-apt-repository ppa:damien-moore/ppa
sudo apt-get update
sudo apt-get install picty
</code></pre><h4 id="_2、从源文件安装" tabindex="-1">2、从源文件安装 <a class="header-anchor" href="#_2、从源文件安装" aria-label="Permalink to “2、从源文件安装”">​</a></h4><p>此外，你还可以从源文件安装。首先安装如下依赖项。</p><pre><code>sudo apt-get install bzr python-pyinotify python-pyexiv2 python-gtk2 python-gnome2 dcraw python-osmgpsmap python-flickrapi
</code></pre><p>然后，使用下面这个命令得到最新版本：</p><pre><code>bzr branch lp:picty
</code></pre><p>要运行Picty，先转到Picty所在的目录，然后输入：</p><pre><code>cd picty
bin/picty
</code></pre><p>要想更新到最新版，请运行：</p><pre><code>cd picty
bzr pull
</code></pre><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h3><p>可以从目录或Unity Dash启动Picty。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/picty_001.png" alt="picty_001"></p><p>你可以选择已存在的收藏集、设备或目录。这里让我们创建一个<strong>新收藏集</strong> ，请先点击新收藏集（New Collection）按钮。进入收藏集，然后浏览到你保存图片的地方。最后，点击<strong>创建（Create）</strong>按钮。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/Create-a-Collection_001.png" alt="Create a Collection_001"></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/picty_002.png" alt="picty_002"></p><p>你可以对每张图片进行修改，旋转，添加/移除标签，设置描述。只需右击任何一个图片然后爱做什么做什么。</p><p>访问下面这个Google组可以得到更多关于Picty相片管理器的信息和支持。</p>`,29)),a("ul",null,[a("li",null,[e(l,{href:"http://groups.google.com/group/pictyphotomanager"},{default:p(()=>[...t[0]||(t[0]=[i("http://groups.google.com/group/pictyphotomanager",-1)])]),_:1})])]),t[15]||(t[15]=a("p",null,"干杯！",-1)),t[16]||(t[16]=a("hr",null,null,-1)),a("p",null,[t[2]||(t[2]=i("via: ",-1)),e(l,{href:"http://www.unixmen.com/picty-managing-photos-made-easy/"},{default:p(()=>[...t[1]||(t[1]=[i("http://www.unixmen.com/picty-managing-photos-made-easy/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=i("作者：",-1)),e(l,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...t[3]||(t[3]=[i("SK",-1)])]),_:1}),t[7]||(t[7]=i(" 译者：",-1)),e(l,{href:"https://github.com/H-mudcup"},{default:p(()=>[...t[4]||(t[4]=[i("H-mudcup",-1)])]),_:1}),t[8]||(t[8]=i(" 校对：",-1)),e(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=i("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[9]||(t[9]=[i("LCTT",-1)])]),_:1}),t[12]||(t[12]=i(" 原创翻译，",-1)),e(l,{href:"http://linux.cn/"},{default:p(()=>[...t[10]||(t[10]=[i("Linux中国",-1)])]),_:1}),t[13]||(t[13]=i(" 荣誉推出",-1))])])}const b=n(u,[["render",y]]);export{w as __pageData,b as default};
